"""LEI format, check digits and consistency. Every LEI here is synthetic and generated by the test."""

import json
from pathlib import Path

import pytest

from micar_linter.ci_outputs import render_annotations, render_sarif, render_summary
from micar_linter.lei import check_digits_for, find_leis, has_valid_check_digits, malformed_leis
from micar_linter.linter import Linter, lint_whitepaper
from micar_linter.rules.common import COMMON_RULES
from micar_linter.whitepaper import Whitepaper, WhitepaperType, load_whitepaper


def _lei(base: str) -> str:
    return base + check_digits_for(base)


ISSUER_LEI = _lei("9999SYNTH0000ZZQ01")
OTHER_LEI = _lei("9999SYNTH0000ZZQ02")
BROKEN_LEI = ISSUER_LEI[:-2] + f"{(int(ISSUER_LEI[-2:]) + 1) % 100:02d}"
RULES = {rule.rule_id: rule for rule in COMMON_RULES}


def _finding(rule_id: str, sections: dict[str, str], language: str = "en"):
    whitepaper = Whitepaper(
        title="Synthetic", type=WhitepaperType.OTHER, sections=sections, metadata={"language": language}
    )
    return Linter((RULES[rule_id],)).lint(whitepaper)[0]


def test_mod_97_10_matches_the_iso_13616_worked_example():
    # Same arithmetic as ISO/IEC 7064 MOD 97-10 in IBANs: GB82 WEST 1234 5698 7654 32, rearranged.
    assert int("".join(str(int(c, 36)) for c in "WEST12345698765432GB82")) % 97 == 1


def test_generated_check_digits_validate_and_one_changed_digit_fails():
    assert has_valid_check_digits(ISSUER_LEI)
    assert has_valid_check_digits(OTHER_LEI)
    assert not has_valid_check_digits(BROKEN_LEI)
    assert not has_valid_check_digits(ISSUER_LEI.lower())
    assert not has_valid_check_digits(ISSUER_LEI[:-1])
    with pytest.raises(ValueError):
        check_digits_for("too-short")


def test_find_leis_needs_a_label_for_purely_numeric_codes_and_ignores_longer_codes():
    numeric = "12345678901234567890"
    text = f"LEI: {ISSUER_LEI}. Account {numeric}. Again {ISSUER_LEI}. Ref X{ISSUER_LEI}9."
    assert find_leis(text) == (ISSUER_LEI,)
    assert find_leis(f"Legal Entity Identifier {numeric}") == (numeric,)


def test_check_digits_rule_fails_closed_without_an_lei():
    # Point 5 of each party Part allows another identifier required pursuant to applicable national law
    # in place of the LEI, so a party section without one goes to review; a draft with no party text
    # stays missing.
    finding = _finding("COMMON.LEI_CHECK_DIGITS", {"issuer": "Synthetic Issuer AG."})
    assert finding.status == "review"
    assert "another identifier" in finding.issues[1]
    assert _finding("COMMON.LEI_CHECK_DIGITS", {}).status == "missing"
    assert _finding("COMMON.LEI_CHECK_DIGITS", {"issuer": "TBD", "summary": "No LEI."}).status == "missing"


def test_check_digits_rule_reviews_a_bad_lei_and_passes_good_ones():
    bad = _finding("COMMON.LEI_CHECK_DIGITS", {"issuer": f"LEI {ISSUER_LEI}", "summary": f"LEI {BROKEN_LEI}"})
    assert bad.status == "review"
    assert len(bad.issues) == 1 and BROKEN_LEI in bad.issues[0] and "'summary'" in bad.issues[0]
    good = _finding("COMMON.LEI_CHECK_DIGITS", {"issuer": f"LEI {ISSUER_LEI}", "offeror": f"LEI {OTHER_LEI}"})
    assert good.status == "pass" and good.issues == ()


def _grouped(code: str, separator: str) -> str:
    return separator.join(code[i : i + 4] for i in range(0, len(code), 4))


# Codes that an LEI label introduces but that are not LEI-shaped. Each is a typo of OTHER_LEI, or a
# fictional number that fails ISO 17442.
MALFORMED = {
    "19 characters": OTHER_LEI[:-1],
    "21 characters": OTHER_LEI[:10] + "7" + OTHER_LEI[10:],
    "letter in a check-digit position": OTHER_LEI[:-1] + "O",
    "lower case": OTHER_LEI.lower(),
    "space-separated groups": _grouped(OTHER_LEI, " "),
    "hyphenated groups": _grouped(OTHER_LEI, "-"),
}


@pytest.mark.parametrize("code", MALFORMED.values(), ids=MALFORMED.keys())
@pytest.mark.parametrize(
    "template", ["LEI: {}.", "The LEI of the offeror is {}.", "Legal entity identifier\n{}", "LEI:\n\n{}"]
)
def test_a_malformed_labelled_lei_next_to_a_valid_one_never_passes(code: str, template: str):
    sections = {"issuer": f"Synthetic Issuer AG. LEI: {ISSUER_LEI}.", "offeror": template.format(code)}
    finding = _finding("COMMON.LEI_CHECK_DIGITS", sections)
    assert finding.status == "review"
    assert finding.issues == (
        f"The code '{code}' after an LEI label in section 'offeror' is not a well-formed LEI "
        "(20 characters: 18 upper-case letters or digits, then two check digits).",
    )
    assert malformed_leis(sections["offeror"]) == (code,)
    # A code that is not an LEI is left to the check-digit rule, as a code with bad check digits is, so one
    # typo is reported once.
    assert _finding("COMMON.LEI_CONSISTENCY", sections).status == "pass"


def test_a_numeric_code_further_from_its_label_still_has_its_check_digits_checked():
    numeric = "12345678901234567890"
    assert not has_valid_check_digits(numeric)
    offeror = f"The LEI of the offeror is {numeric}."
    assert find_leis(offeror) == (numeric,)
    finding = _finding("COMMON.LEI_CHECK_DIGITS", {"issuer": f"LEI: {ISSUER_LEI}.", "offeror": offeror})
    assert finding.status == "review"
    assert finding.issues == (
        f"LEI '{numeric}' in section 'offeror' fails the ISO/IEC 7064 MOD 97-10 check digits.",
    )


def test_a_malformed_lei_without_a_valid_one_keeps_the_no_lei_status():
    # The no-LEI statuses stay as they were; the malformed code is named after the no-LEI message.
    review = _finding("COMMON.LEI_CHECK_DIGITS", {"issuer": f"LEI: {OTHER_LEI[:-1]}."})
    assert review.status == "review" and len(review.issues) == 3
    assert OTHER_LEI[:-1] in review.issues[2]
    missing = _finding("COMMON.LEI_CHECK_DIGITS", {"summary": f"LEI: {OTHER_LEI[:-1]}."})
    assert missing.status == "missing" and OTHER_LEI[:-1] in missing.issues[1]


@pytest.mark.parametrize(
    "text",
    [
        f"LEI {OTHER_LEI} AG.",
        "The LEI will be obtained by 1 March 2026.",
        "LEI as required by Article 2(1)(b) of Implementing Regulation (EU) 2024/2984.",
        "LEI: none. The national register number is HRB 1234567890.",
        "LEI eligibility: TRUE",
        # The next field of the numbered layout is not the code of a label answered in words.
        "Legal entity identifier: not available\nContact telephone number: +49 69 0000 0000",
        "Prețul de 10 lei se plătește în contul IBAN RO00SYNTH00000000000000.",
        f"Its fictional Legal Entity Identifier (LEI), synthetic and not registered, is {OTHER_LEI}.",
    ],
)
def test_labels_without_a_malformed_code_leave_the_rule_alone(text: str):
    assert malformed_leis(text) == ()
    sections = {"issuer": f"Synthetic Issuer AG. LEI: {ISSUER_LEI}.", "offeror": f"LEI {OTHER_LEI}. {text}"}
    assert _finding("COMMON.LEI_CHECK_DIGITS", sections).status == "pass"


@pytest.mark.parametrize(
    ("sections", "status"),
    [
        ({"summary": f"LEI {ISSUER_LEI}"}, "missing"),
        ({"issuer": f"LEI {BROKEN_LEI}"}, "review"),
        ({"issuer": "Synthetic Issuer AG, register number HRB 0000.", "summary": f"LEI {ISSUER_LEI}"}, "review"),
        ({"issuer": f"LEI {ISSUER_LEI}", "summary": f"LEI {OTHER_LEI}"}, "review"),
        ({"issuer": f"LEI {ISSUER_LEI} or {OTHER_LEI}"}, "review"),
        (
            {"issuer": f"LEI {ISSUER_LEI}", "offeror": f"LEI {OTHER_LEI}", "summary": f"LEIs {OTHER_LEI}"},
            "pass",
        ),
        ({"issuer": f"LEI {ISSUER_LEI}", "summary": f"LEI {ISSUER_LEI}, earlier {BROKEN_LEI}"}, "pass"),
    ],
)
def test_consistency_rule(sections, status):
    assert _finding("COMMON.LEI_CONSISTENCY", sections).status == status


def test_german_drafts_get_german_messages():
    no_lei = _finding("COMMON.LEI_CHECK_DIGITS", {"issuer": "Emittent"}, language="de")
    assert "Rechtsträgerkennung" in no_lei.issues[0] and "nationalem Recht" in no_lei.issues[1]
    review = _finding("COMMON.LEI_CONSISTENCY", {"issuer": f"LEI {ISSUER_LEI}", "summary": OTHER_LEI}, "de")
    assert "erscheint in keinem Abschnitt" in review.issues[0]
    sections = {"issuer": f"LEI {ISSUER_LEI}", "offeror": f"Rechtsträgerkennung: {OTHER_LEI[:-1]}"}
    malformed = _finding("COMMON.LEI_CHECK_DIGITS", sections, "de")
    assert malformed.status == "review"
    assert malformed.issues == (
        f"Der Code '{OTHER_LEI[:-1]}' nach der LEI-Angabe im Abschnitt 'offeror' ist keine korrekt "
        "gebildete LEI (20 Zeichen: 18 Großbuchstaben oder Ziffern, dann zwei Prüfziffern).",
    )


def test_lei_rules_run_for_every_regime():
    for regime in WhitepaperType:
        whitepaper = Whitepaper(title="t", type=regime, sections={}, metadata={})
        ids = {f.rule.rule_id for f in lint_whitepaper(whitepaper).findings}
        assert {"COMMON.LEI_CHECK_DIGITS", "COMMON.LEI_CONSISTENCY"} <= ids


def test_ci_outputs_never_echo_an_lei(tmp_path: Path):
    path = tmp_path / "draft.json"
    draft = {
        "title": "t",
        "type": "other",
        "sections": {"issuer": f"LEI {ISSUER_LEI}", "summary": BROKEN_LEI},
    }
    path.write_text(json.dumps(draft), encoding="utf-8")
    report = lint_whitepaper(load_whitepaper(path))
    statuses = {f.rule.rule_id: f.status for f in report.findings}
    assert statuses["COMMON.LEI_CHECK_DIGITS"] == "review"
    for output in (
        render_sarif(report, path),
        render_summary(report, path),
        render_annotations(report, path),
    ):
        assert ISSUER_LEI not in output and BROKEN_LEI not in output


@pytest.mark.parametrize("name", ["other-crypto-asset.json", "art-stablecoin.json", "emt-token.json"])
def test_full_synthetic_examples_carry_a_valid_lei(name):
    path = Path(__file__).resolve().parents[1] / "examples" / name
    findings = {f.rule.rule_id: f.status for f in lint_whitepaper(load_whitepaper(path)).findings}
    assert findings["COMMON.LEI_CHECK_DIGITS"] == "pass"
    assert findings["COMMON.LEI_CONSISTENCY"] == "pass"
    assert "SYNTH" in " ".join(find_leis(path.read_text(encoding="utf-8")))
